#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, k;
    cin >> n >> k;

    vector<int> vec(n);
    for (int& x : vec) cin >> x;

    int count = 0;
    int c = vec[k - 1];

    while (count < n && vec[count] > 0 && vec[count] >= c) {
        ++count;
    }

    cout << count;
    return 0;
}

